static inline T_LspDiag *vu_at_L_S_LspDiag(L_S_LspDiag *l, int64_t i, int line) {
    /* one unsigned comparison: also catches i < 0, and measured faster than two signed ones (n-body 17%) */
    if (__builtin_expect((uint64_t)i >= (uint64_t)l->len, 0)) vu_oob(i, l->len, line);
    return &l->data[i];
}
/* A read in a tried loop (vu_vf_add in the runtime): out of range records a failure and reads a zero. */
/* (const after the element type: for a list of pointers, the pointers are what's const) */
static inline T_LspDiag const *vu_vfat_L_S_LspDiag(const L_S_LspDiag *l, int64_t i, uint64_t *f) {
    static T_LspDiag const zero;
    int in = (uint64_t)i < (uint64_t)l->len;
    *f |= (uint64_t)!in;
    return in ? &l->data[i] : &zero;
}
/* xs[a..b] (let part = xs[a..b]): the elements in place, read-only and never freed; the list it's
   part of is frozen while the view lives. */
static inline L_S_LspDiag vu_view_L_S_LspDiag(const L_S_LspDiag *l, int64_t a, int64_t b, int line) {
    if (a < 0 || b < a || b > l->len)
        vu_fail(line, "slice %lld..%lld out of bounds for a list of length %lld", (long long)a, (long long)b, (long long)l->len);
    L_S_LspDiag r = { .data = l->data ? l->data + a : NULL, .len = b - a, .cap = 0 };   /* (NULL + 0 is undefined) */
    return r;
}
/* var part = xs[a..b]: a copy (plain values only, checked by the compiler). */
static L_S_LspDiag vu_sub_L_S_LspDiag(const L_S_LspDiag *l, int64_t a, int64_t b, int line) {
    if (a < 0 || b < a || b > l->len)
        vu_fail(line, "slice %lld..%lld out of bounds for a list of length %lld", (long long)a, (long long)b, (long long)l->len);
    L_S_LspDiag r = {0};
    if (b > a) {
        r.data = (T_LspDiag *)vu_malloc((size_t)(b - a) * sizeof(T_LspDiag));
        memcpy(r.data, l->data + a, (size_t)(b - a) * sizeof(T_LspDiag));
        r.len = r.cap = b - a;
    }
    return r;
}
static void vu_grow_L_S_LspDiag(L_S_LspDiag *l) {
    if (l->cap > (int64_t)(PTRDIFF_MAX / sizeof(T_LspDiag) / 2)) vu_oom();
    int64_t c = l->cap ? l->cap * 2 : 4;
    T_LspDiag *d = (T_LspDiag *)realloc(l->data, (size_t)c * sizeof(T_LspDiag));
    if (!d) vu_oom();
    l->data = d;
    l->cap = c;
}
static void vu_reserve_L_S_LspDiag(L_S_LspDiag *l, int64_t n, int line) {
    if (n < 0) vu_fail(line, "reserve(%lld): the count can't be negative", (long long)n);
    if (n <= l->cap - l->len) return;
    if (n > (int64_t)(PTRDIFF_MAX / sizeof(T_LspDiag)) - l->len) vu_oom();
    int64_t c = l->len + n;
    T_LspDiag *d = (T_LspDiag *)realloc(l->data, (size_t)c * sizeof(T_LspDiag));
    if (!d) vu_oom();
    l->data = d;
    l->cap = c;
}
static inline T_LspDiag vu_pop_L_S_LspDiag(L_S_LspDiag *l, int line) {
    if (__builtin_expect(l->len == 0, 0)) vu_fail(line, "pop() from an empty list");
    return l->data[--l->len];
}
static inline void vu_push_L_S_LspDiag(L_S_LspDiag *l, T_LspDiag v) {
    if (l->len == l->cap) vu_grow_L_S_LspDiag(l);
    l->data[l->len++] = v;
}
static L_S_LspDiag vu_rep_L_S_LspDiag(L_S_LspDiag src, int64_t n, int line) {
    L_S_LspDiag r = {0};
    if (n > 0 && src.len > 0) {
        if (n > INT64_MAX / src.len || src.len * n > (int64_t)(PTRDIFF_MAX / sizeof(T_LspDiag)))
            vu_fail(line, "list of %lld x %lld elements is too large", (long long)src.len, (long long)n);
        int64_t total = src.len * n;
        r.data = (T_LspDiag *)vu_malloc((size_t)total * sizeof(T_LspDiag));
        r.len = r.cap = total;
        if (src.len == 1) { T_LspDiag v = src.data[0]; for (int64_t k = 0; k < total; k++) r.data[k] = v; }
        else for (int64_t k = 0; k < n; k++) memcpy(r.data + k * src.len, src.data, (size_t)src.len * sizeof(T_LspDiag));
    }
    free(src.data);
    return r;
}
